import { describe, it } from "node:test";
import assert from "node:assert/strict";
import type { PublicClient } from "viem";
import { checkPrice } from "./check.js";

const FEED = "0x5f4eC3Df9cbd43714FE2740f5E3616155c5b8419";
const BTC_FEED = "0xF4030086522a5bEEa4988F8cA5B36dbC97BeE88c";
const RPC = "https://ethereum-rpc.publicnode.com";
const NOW = 1_724_520_000;

function mockClient(opts: {
  answer: bigint;
  updatedAt: bigint;
  decimals: number | bigint | Error;
  roundId?: bigint;
  answeredInRound?: bigint;
  chainId?: number | Error;
  seqAnswer?: bigint;
  seqStartedAt?: bigint;
}): Pick<PublicClient, "readContract"> & { getChainId?: PublicClient["getChainId"] } {
  const client: Pick<PublicClient, "readContract"> & { getChainId?: PublicClient["getChainId"] } = {
    readContract: (async ({ address, functionName }: { address: string; functionName: string }) => {
      if (functionName === "latestRoundData") {
        if (
          address === "0xFdB631F5EE196F0ed6FAa767959853A9F217697D" ||
          address === "0x371EAD81c9102C9BF4874A9075FFFf170F2Ee389" ||
          address === "0xBCF85224fc0756B9Fa45aA7892530B47e10b6433"
        ) {
          return [1n, opts.seqAnswer ?? 0n, opts.seqStartedAt ?? 1n, 1n, 1n] as const;
        }

        // (roundId, answer, startedAt, updatedAt, answeredInRound)
        return [
          opts.roundId ?? 1n,
          opts.answer,
          1n,
          opts.updatedAt,
          opts.answeredInRound ?? 1n,
        ] as const;
      }
      if (functionName === "decimals") {
        if (opts.decimals instanceof Error) throw opts.decimals;
        return opts.decimals;
      }
      throw new Error(`unexpected ${functionName}`);
    }) as unknown as PublicClient["readContract"],
  };
  if (opts.chainId !== undefined) {
    client.getChainId = async () => {
      if (opts.chainId instanceof Error) throw opts.chainId;
      return opts.chainId!;
    };
  }
  return client;
}

describe("checkPrice (mocked viem, no live RPC)", () => {
  it("fresh ALLOW", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      amountEth: 0.5,
      nowSeconds: NOW,
      __client: mockClient({ answer: 300000000000n, updatedAt: BigInt(NOW - 10), decimals: 8 }),
    });
    assert.equal(r.decision, "ALLOW");
    assert.equal(r.allowExecute, true);
    assert.equal(r.ageSeconds, 10);
    assert.equal(r.priceUsd, 3000);
    assert.equal(r.quoteUsd, 1500);
    assert.equal(r.answer, "300000000000");
  });

  it("stale BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      amountEth: null,
      nowSeconds: NOW,
      __client: mockClient({ answer: 300000000000n, updatedAt: BigInt(NOW - 100), decimals: 8 }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.equal(r.ageSeconds, 100);
  });

  it("updatedAt 0 BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({ answer: 300000000000n, updatedAt: 0n, decimals: 8 }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /updatedAt is 0/);
  });

  it("answer <=0 BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({ answer: 0n, updatedAt: BigInt(NOW - 10), decimals: 8 }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /answer is 0/);

    const r2 = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({ answer: -1n, updatedAt: BigInt(NOW - 10), decimals: 8 }),
    });
    assert.equal(r2.decision, "BLOCK");
  });

  it("decimals throw BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: new Error("decimals down"),
      }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /decimals/);
  });

  it("incomplete round BLOCK — answeredInRound < roundId with fresh updatedAt", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        roundId: 2n,
        answeredInRound: 1n,
      }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /answeredInRound.*roundId|incomplete round/);
  });

  it("complete round fresh ALLOW — answeredInRound == roundId", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        roundId: 5n,
        answeredInRound: 5n,
      }),
    });
    assert.equal(r.decision, "ALLOW");
    assert.equal(r.allowExecute, true);
    assert.equal(r.ageSeconds, 10);
  });

  it("chainId 1 with default feed fresh ALLOW", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: 1,
      }),
    });
    assert.equal(r.decision, "ALLOW");
    assert.equal(r.allowExecute, true);
    assert.match(r.reason, /fresh/);
  });

  it("chainId mismatch BLOCK — Sepolia rpc with mainnet feed", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: 11155111,
      }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /chainId mismatch/);
  });

  it("getChainId throw → BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: new Error("chainId down"),
      }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /failed to get chainId/);
  });

  it("BTC/USD in registry + chainId 1 + complete fresh → ALLOW", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: BTC_FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 6100000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: 1,
      }),
    });
    assert.equal(r.decision, "ALLOW");
    assert.equal(r.allowExecute, true);
    assert.equal(r.priceUsd, 61000);
  });

  it("BTC/USD + chainId 11155111 → BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: BTC_FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 6100000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: 11155111,
      }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /chainId mismatch/);
  });

  it("unknown feed not in registry — BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: "0xabc0000000000000000000000000000000000000",
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({ answer: 300000000000n, updatedAt: BigInt(NOW - 10), decimals: 8 }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.equal(r.allowExecute, false);
    assert.match(r.reason, /unknown\/unsupported feed/);
  });

  it("malformed RPC and invalid feed — fail closed", async () => {
    // invalid feed address → BLOCK before RPC
    const rFeed = await checkPrice({
      rpc: RPC,
      feed: "0xbad",
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({ answer: 300000000000n, updatedAt: BigInt(NOW - 10), decimals: 8 }),
    });
    assert.equal(rFeed.decision, "BLOCK");
    assert.match(rFeed.reason, /invalid feed/);

    // missing rpc → BLOCK
    const rRpc = await checkPrice({
      rpc: "",
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({ answer: 300000000000n, updatedAt: BigInt(NOW - 10), decimals: 8 }),
    });
    assert.equal(rRpc.decision, "BLOCK");
    assert.match(rRpc.reason, /missing rpc/);

    // malformed readContract throws generic → BLOCK
    const badClient = {
      readContract: (async () => {
        throw new Error("malformed response: unexpected tuple");
      }) as unknown as PublicClient["readContract"],
    };
    const rMal = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: badClient,
    });
    assert.equal(rMal.decision, "BLOCK");
    assert.match(rMal.reason, /failed to read/);

    // invalid maxAge → BLOCK
    const rPolicy = await checkPrice({
      rpc: RPC,
      feed: FEED,
      maxAgeSeconds: NaN,
      nowSeconds: NOW,
      __client: mockClient({ answer: 300000000000n, updatedAt: BigInt(NOW - 10), decimals: 8 }),
    });
    assert.equal(rPolicy.decision, "BLOCK");
    assert.match(rPolicy.reason, /invalid maxAge/);
  });

  it("sequencer DOWN -> BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: "0x639Fe6ab55C921f74e7fac1ee960C0B6293ba612", // Arbitrum ETH/USD
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: 42161,
        seqAnswer: 1n, // DOWN
      }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.match(r.reason, /L2 Sequencer is DOWN/);
  });

  it("sequencer GRACE PERIOD -> BLOCK", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: "0x639Fe6ab55C921f74e7fac1ee960C0B6293ba612", // Arbitrum ETH/USD
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: 42161,
        seqAnswer: 0n, // UP
        seqStartedAt: BigInt(NOW - 100), // 100s ago (< 3600s grace period)
      }),
    });
    assert.equal(r.decision, "BLOCK");
    assert.match(r.reason, /grace period/);
  });

  it("sequencer UP and past grace period -> ALLOW", async () => {
    const r = await checkPrice({
      rpc: RPC,
      feed: "0x639Fe6ab55C921f74e7fac1ee960C0B6293ba612", // Arbitrum ETH/USD
      maxAgeSeconds: 60,
      nowSeconds: NOW,
      __client: mockClient({
        answer: 300000000000n,
        updatedAt: BigInt(NOW - 10),
        decimals: 8,
        chainId: 42161,
        seqAnswer: 0n, // UP
        seqStartedAt: BigInt(NOW - 4000), // 4000s ago (> 3600s grace period)
      }),
    });
    assert.equal(r.decision, "ALLOW");
  });
});

import { createPublicClient, http, parseAbi, type PublicClient } from "viem";
import { mainnet } from "viem/chains";
import { isStale } from "./isStale.js";
import { quoteFromFeed } from "./quote.js";
import { lookupFeed } from "./feeds.js";
import { checkSequencer } from "./sequencer.js";

/**
 * Official Data Feed ABI — only `decimals` and `latestRoundData` per
 * https://docs.chain.link/data-feeds/api-reference
 */
const feedAbi = parseAbi([
  "function decimals() view returns (uint8)",
  "function latestRoundData() view returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)",
] as const);

export type CheckPriceInput = {
  rpc: string;
  feed: string;
  maxAgeSeconds: number;
  amountEth?: number | null;
  nowSeconds?: number;
  /** @internal inject mock client for tests (no live RPC) — viem-compatible */
  __client?: Pick<PublicClient, "readContract"> & { getChainId?: PublicClient["getChainId"] };
};

export type CheckPriceResult = {
  decision: "ALLOW" | "BLOCK";
  reason: string;
  feed: string;
  answer: string;
  priceUsd: number | null;
  amountEth: number | null;
  quoteUsd: number | null;
  updatedAt: string;
  ageSeconds: number | null;
  maxAgeSeconds: number;
  now: number;
  allowExecute: boolean;
};

function blockResult(
  input: CheckPriceInput,
  reason: string,
  partial?: Partial<CheckPriceResult>,
): CheckPriceResult {
  const now = input.nowSeconds ?? Math.floor(Date.now() / 1000);
  return {
    decision: "BLOCK",
    reason,
    feed: input.feed,
    answer: partial?.answer ?? "0",
    priceUsd: partial?.priceUsd ?? null,
    amountEth: input.amountEth ?? null,
    quoteUsd: partial?.quoteUsd ?? null,
    updatedAt: partial?.updatedAt ?? "0",
    ageSeconds: partial?.ageSeconds ?? null,
    maxAgeSeconds: input.maxAgeSeconds,
    now,
    allowExecute: false,
  };
}

/**
 * Full check: viem `latestRoundData` + `decimals` → `isStale` → `quoteFromFeed`.
 * Fail closed on any RPC/read/zero/negative/invalid. No wallet, no write.
 * Verified against viem `createPublicClient` + `readContract` docs.
 */
export async function checkPrice(input: CheckPriceInput): Promise<CheckPriceResult> {
  const { rpc, feed, maxAgeSeconds, amountEth } = input;
  const now = input.nowSeconds ?? Math.floor(Date.now() / 1000);

  if (amountEth !== undefined && amountEth !== null) {
    if (typeof amountEth !== "number" || !Number.isFinite(amountEth) || amountEth < 0) {
      return blockResult(input, `invalid amountEth ${String(amountEth)} — BLOCK (fail closed)`);
    }
  }
  if (!/^0x[a-fA-F0-9]{40}$/.test(feed)) {
    return blockResult(input, `invalid feed ${feed} — BLOCK`);
  }

  const feedEntry = lookupFeed(feed);
  if (!feedEntry) {
    return blockResult(input, `unknown/unsupported feed ${feed} — BLOCK`);
  }
  if (!Number.isFinite(maxAgeSeconds) || !Number.isInteger(maxAgeSeconds) || maxAgeSeconds < 0) {
    return blockResult(input, `invalid maxAgeSeconds ${String(maxAgeSeconds)} — BLOCK`);
  }
  if (typeof rpc !== "string" || rpc.trim() === "") {
    return blockResult(input, "missing rpc — BLOCK (fail closed)");
  }

  const client =
    input.__client ??
    createPublicClient({
      chain: mainnet,
      transport: http(rpc),
    });

  // Chain binding: registry entry's chainId must match RPC chainId
  // Skip getChainId when __client is injected and mock does not implement it (existing tests)
  const maybeGetChainId = (client as unknown as { getChainId?: () => Promise<number> }).getChainId;
  if (typeof maybeGetChainId === "function") {
    try {
      const chainId = await maybeGetChainId.call(client);
      if (chainId !== feedEntry.chainId) {
        return blockResult(
          input,
          `chainId mismatch: feed ${feed} is chainId ${feedEntry.chainId} but rpc returned chainId ${String(chainId)} — BLOCK`,
        );
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return blockResult(input, `failed to get chainId — BLOCK (fail closed): ${msg}`);
    }
  }

  // Sequencer Liveness Check (Fail closed)
  const seqError = await checkSequencer(feedEntry.chainId, client, feedAbi, now);
  if (seqError) {
    return blockResult(input, seqError);
  }

  // Parallel reads — viem batches `eth_call` at end of tick (public client docs)
  let roundId: bigint;
  let answer: bigint;
  let updatedAt: bigint;
  let answeredInRound: bigint;
  let decimals: number;

  try {
    const [roundData, dec] = await Promise.all([
      client.readContract({
        address: feed as `0x${string}`,
        abi: feedAbi,
        functionName: "latestRoundData",
      }) as Promise<readonly [bigint, bigint, bigint, bigint, bigint]>,
      client.readContract({
        address: feed as `0x${string}`,
        abi: feedAbi,
        functionName: "decimals",
      }) as Promise<number | bigint>,
    ]);

    const data = roundData;
    roundId = data[0];
    answer = data[1];
    updatedAt = data[3];
    answeredInRound = data[4];

    const d = dec;
    decimals = typeof d === "bigint" ? Number(d) : d;
    if (!Number.isInteger(decimals) || decimals < 0 || decimals > 36) {
      throw new Error(`invalid decimals ${String(d)}`);
    }

    if (updatedAt === 0n) {
      return blockResult(input, `updatedAt is 0 (no data) from ${feed} — BLOCK`, {
        answer: answer.toString(),
        updatedAt: updatedAt.toString(),
        ageSeconds: null,
      });
    }
    if (answer <= 0n) {
      return blockResult(
        input,
        `answer is ${answer.toString()} (invalid price) from ${feed} — BLOCK`,
        {
          answer: answer.toString(),
          updatedAt: updatedAt.toString(),
          ageSeconds: null,
        },
      );
    }
    if (answeredInRound < roundId) {
      return blockResult(
        input,
        `incomplete round: answeredInRound ${answeredInRound.toString()} < roundId ${roundId.toString()} (unanswered round) from ${feed} — BLOCK`,
        {
          answer: answer.toString(),
          updatedAt: updatedAt.toString(),
          ageSeconds: null,
        },
      );
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    // Distinguish which call failed by message; keep generic fail-closed
    if (msg.includes("decimals")) {
      return blockResult(
        input,
        `failed to read decimals() from ${feed} — BLOCK (fail closed): ${msg}`,
      );
    }
    return blockResult(
      input,
      `failed to read latestRoundData from ${feed} — BLOCK (fail closed): ${msg}`,
    );
  }

  const stale = isStale({ updatedAt, nowSeconds: now, maxAgeSeconds });

  let priceUsd: number | null = null;
  let quoteUsd: number | null = null;
  try {
    const q = quoteFromFeed({ answer, decimals, amountEth: amountEth ?? null });
    priceUsd = q.priceUsd;
    quoteUsd = q.quoteUsd;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return {
      decision: "BLOCK",
      reason: `quote failed: ${msg} — BLOCK`,
      feed,
      answer: answer.toString(),
      priceUsd: null,
      amountEth: amountEth ?? null,
      quoteUsd: null,
      updatedAt: updatedAt.toString(),
      ageSeconds: stale.ageSeconds,
      maxAgeSeconds,
      now,
      allowExecute: false,
    };
  }

  const allowExecute = stale.decision === "ALLOW";
  return {
    decision: stale.decision,
    reason: stale.reason,
    feed,
    answer: answer.toString(),
    priceUsd,
    amountEth: amountEth ?? null,
    quoteUsd,
    updatedAt: updatedAt.toString(),
    ageSeconds: stale.ageSeconds,
    maxAgeSeconds,
    now,
    allowExecute,
  };
}

import { formatUnits } from "viem";

export type QuoteInput = {
  answer: bigint;
  decimals: number | bigint;
  amountEth?: number | null;
};

export type QuoteResult = {
  priceUsd: number;
  quoteUsd: number | null;
};

/**
 * Price math from official Data Feed `answer` + `decimals`.
 * Fail closed: bad answer/decimals/amount throw — caller converts to BLOCK.
 * Uses viem `formatUnits` per https://viem.sh/docs/utilities/formatUnits
 */
export function quoteFromFeed({ answer, decimals, amountEth }: QuoteInput): QuoteResult {
  if (typeof answer !== "bigint") {
    throw new Error("answer must be bigint");
  }
  if (answer <= 0n) {
    throw new Error(`invalid answer ${answer.toString()}`);
  }

  const dec = typeof decimals === "bigint" ? Number(decimals) : decimals;
  if (typeof dec !== "number" || !Number.isInteger(dec) || dec < 0 || dec > 36) {
    throw new Error(`invalid decimals ${String(decimals)}`);
  }

  if (amountEth !== undefined && amountEth !== null) {
    if (typeof amountEth !== "number" || !Number.isFinite(amountEth) || amountEth < 0) {
      throw new Error(`invalid amountEth ${String(amountEth)}`);
    }
  }

  // viem formatUnits: string value scaled by decimals, e.g. 245377000000n + 8 → "2453.77"
  const priceUsd = Number(formatUnits(answer, dec));
  if (!Number.isFinite(priceUsd) || priceUsd < 0) {
    throw new Error(`invalid priceUsd ${String(priceUsd)}`);
  }

  const quoteUsd = amountEth != null ? amountEth * priceUsd : null;
  if (quoteUsd !== null && (!Number.isFinite(quoteUsd) || quoteUsd < 0)) {
    throw new Error(`invalid quoteUsd ${String(quoteUsd)}`);
  }

  return { priceUsd, quoteUsd };
}

export type Decision = "ALLOW" | "BLOCK";

export type IsStaleInput = {
  updatedAt: bigint | number | string | null | undefined;
  nowSeconds: number;
  maxAgeSeconds: number;
};

export type IsStaleResult = {
  decision: Decision;
  ageSeconds: number | null;
  reason: string;
};

/**
 * Pure freshness check — no RPC. Fail closed on missing, unparseable, or future timestamp.
 * Safe to unit-test and reuse in CRE workflows.
 * Official field: Data Feed `latestRoundData.updatedAt` (uint80 seconds).
 */
export function isStale({ updatedAt, nowSeconds, maxAgeSeconds }: IsStaleInput): IsStaleResult {
  // Validate window first — bad window is BLOCK (fail closed, no partial age)
  if (!Number.isFinite(nowSeconds) || !Number.isInteger(maxAgeSeconds)) {
    return {
      decision: "BLOCK",
      ageSeconds: null,
      reason: "missing or invalid now/maxAge — BLOCK (fail closed)",
    };
  }
  if (maxAgeSeconds < 0) {
    return {
      decision: "BLOCK",
      ageSeconds: null,
      reason: "maxAgeSeconds must be >= 0 — BLOCK",
    };
  }

  // Parse updatedAt → seconds (fail closed on any unparseable)
  let updatedAtSeconds: number;
  try {
    if (updatedAt === null || updatedAt === undefined) throw new Error("missing");

    if (typeof updatedAt === "bigint") {
      if (updatedAt < 0n) throw new Error("negative");
      // Use Number for age math; updatedAt fits in 53 bits (uint80 but timestamp < 2^31)
      updatedAtSeconds = Number(updatedAt);
    } else if (typeof updatedAt === "number") {
      if (!Number.isFinite(updatedAt)) throw new Error("not finite");
      updatedAtSeconds = Math.trunc(updatedAt);
    } else if (typeof updatedAt === "string") {
      const s = updatedAt.trim();
      if (s === "") throw new Error("empty");
      if (s.startsWith("0x") || s.startsWith("0X")) {
        updatedAtSeconds = Number(BigInt(s));
      } else {
        const n = Number(s);
        if (!Number.isFinite(n)) throw new Error("not finite");
        updatedAtSeconds = Math.trunc(n);
      }
    } else {
      throw new Error("unsupported type");
    }

    if (!Number.isFinite(updatedAtSeconds) || updatedAtSeconds < 0) {
      throw new Error("invalid seconds");
    }
  } catch {
    return {
      decision: "BLOCK",
      ageSeconds: null,
      reason: "missing or unparseable updatedAt — BLOCK (fail closed)",
    };
  }

  const nowTrunc = Math.trunc(nowSeconds);
  const ageSeconds = nowTrunc - updatedAtSeconds;

  // not-yet-valid is BLOCK — clock skew or future timestamp (per AGENTS.md)
  if (ageSeconds < 0) {
    return {
      decision: "BLOCK",
      ageSeconds,
      reason: `not-yet-valid: updatedAt ${updatedAtSeconds} is in the future (now ${nowTrunc}) — BLOCK`,
    };
  }
  if (ageSeconds > maxAgeSeconds) {
    return {
      decision: "BLOCK",
      ageSeconds,
      reason: `stale: age ${ageSeconds}s > maxAge ${maxAgeSeconds}s — BLOCK`,
    };
  }
  return {
    decision: "ALLOW",
    ageSeconds,
    reason: `fresh: age ${ageSeconds}s <= maxAge ${maxAgeSeconds}s — ALLOW`,
  };
}

